import { Button, Popover, Text } from '@design-schema/rn';

<Popover
  trigger={<Button label="Filters" variant="secondary" />}
  heading="Filters"
  dismissible={false}
  open
>
  <Text>Filter results by status and date.</Text>
</Popover>

import * as React from 'react';
import { Button, Input, Link, Popover, Stack } from '@design-schema/rn';

function Open(): React.JSX.Element {
  const [open, setOpen] = React.useState(true);
  return (
    <Popover
      heading="Filters"
      trigger={<Button label="Filters" variant="secondary" />}
      open={open}
      onOpenChange={(next) => setOpen(next)}
    >
      <Stack gap="normal" align="start">
        <Input label="Search" name="search" />
        <Link href="https://example.com/filters" label="Reset filters" />
        <Button label="Apply" onPress={() => setOpen(false)} />
      </Stack>
    </Popover>
  );
}

<Open />
